  package    com . cronutils . utils . descriptor ;   import   java . util . Locale ;  import   org . junit . Before ;  import   org . junit . Test ;  import    com . cronutils . descriptor . CronDescriptor ;  import    com . cronutils . model . CronType ;  import     com . cronutils . model . definition . CronDefinitionBuilder ;  import    com . cronutils . parser . CronParser ;  import static    org . junit . Assert . assertEquals ;   public class CronDescriptorCron4jIntegrationTest  {   private static final String  EVERY_MINUTE_EXPECTED = "every minute" ;   private CronDescriptor  descriptor ;   private CronParser  parser ;    @ Before public void setUp  ( )  {   descriptor =  CronDescriptor . instance  (  Locale . UK ) ;   parser =  new CronParser  (  CronDefinitionBuilder . instanceDefinitionFor  (  CronType . CRON4J ) ) ; }    @ Test public void testEveryMinuteBetween1100And1110  ( )  {   assertEquals  ( "every minute between 11:00 and 11:10" ,  descriptor . describe  (  parser . parse  ( "0-10 11 * * *" ) ) ) ; }    @ Test public void testEveryMinute  ( )  {   assertEquals  ( EVERY_MINUTE_EXPECTED ,  descriptor . describe  (  parser . parse  ( "* * * * *" ) ) ) ;   assertEquals  ( EVERY_MINUTE_EXPECTED ,  descriptor . describe  (  parser . parse  ( "*/1 * * * *" ) ) ) ;   assertEquals  ( EVERY_MINUTE_EXPECTED ,  descriptor . describe  (  parser . parse  ( "0/1 * * * *" ) ) ) ; }    @ Test public void testEveryFiveMinutes  ( )  {   assertEquals  ( "every 5 minutes" ,  descriptor . describe  (  parser . parse  ( "*/5 * * * *" ) ) ) ;   assertEquals  ( "every 5 minutes" ,  descriptor . describe  (  parser . parse  ( "0/5 * * * *" ) ) ) ; }    @ Test public void testAtElevenThirty  ( )  {   assertEquals  ( "at 11:30" ,  descriptor . describe  (  parser . parse  ( "30 11 * * *" ) ) ) ; }    @ Test public void testAtTwentyThreeFromMondayThroughFriday  ( )  {   assertEquals  ( "at 23:00 every day between Monday and Friday" ,  descriptor . describe  (  parser . parse  ( "0 23 * * MON-FRI" ) ) ) ;   assertEquals  ( "at 23:00 every day between Monday and Friday" ,  descriptor . describe  (  parser . parse  ( "0 23 * * 1-5" ) ) ) ; }    @ Test public void testDescribeIssue32Expression01  ( )  {   final String  cronExpr = "* 1,2,3,4,5,6 * 1,2,3 *" ;   descriptor . describe  (  parser . parse  ( cronExpr ) ) ; }    @ Test public void testDescribeIssue32Expression02  ( )  {   final String  cronExpr = "* 1 1,2 * 4" ;   descriptor . describe  (  parser . parse  ( cronExpr ) ) ; } }